BEGIN;
SELECT plan(22);
SELECT has_table('public','romax_gmail_import_audit','audit table exists');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.romax_gmail_import_audit'::regclass),'audit RLS');
SELECT ok(NOT has_table_privilege('authenticated','public.romax_gmail_import_audit','SELECT'),'client cannot read audit');
SELECT ok(NOT has_table_privilege('authenticated','public.romax_gmail_import_audit','INSERT'),'client cannot insert audit');
SELECT ok(NOT has_table_privilege('service_role','public.romax_gmail_import_audit','UPDATE'),'audit cannot be updated by server');
SELECT ok(NOT has_table_privilege('service_role','public.romax_gmail_import_audit','DELETE'),'audit cannot be deleted by server');
SELECT ok(NOT has_function_privilege('authenticated','public.romax_confirm_gmail_import(uuid,uuid,timestamptz,text,text,timestamptz,text,text,text,text,timestamptz,text,text)','EXECUTE'),'browser cannot call importer');
SELECT ok(NOT has_function_privilege('anon','public.romax_confirm_gmail_import(uuid,uuid,timestamptz,text,text,timestamptz,text,text,text,text,timestamptz,text,text)','EXECUTE'),'anonymous cannot call importer');
SELECT ok(has_function_privilege('service_role','public.romax_confirm_gmail_import(uuid,uuid,timestamptz,text,text,timestamptz,text,text,text,text,timestamptz,text,text)','EXECUTE'),'trusted server can call importer');
INSERT INTO auth.users(id,email) VALUES ('d3100000-0000-4000-8000-000000000002','gmail-owner@example.test'),('d3100000-0000-4000-8000-000000000003','gmail-manager@example.test');
INSERT INTO public.organizations(id,name,organization_type,status) VALUES ('d3100000-0000-4000-8000-000000000001','Synthetic Gmail QA','provider_company','active'),('d3100000-0000-4000-8000-000000000004','Synthetic other QA','provider_company','active');
INSERT INTO public.organization_members(organization_id,user_id,role,is_active) VALUES ('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000002','owner',true),('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000003','manager',true);
INSERT INTO public.romax_gmail_connections(organization_id,status,mailbox_email,refresh_ciphertext,connected_by,connected_at) VALUES ('d3100000-0000-4000-8000-000000000001','connected','synthetic@example.test','synthetic-ciphertext','d3100000-0000-4000-8000-000000000002','2026-01-01T00:00:00Z');

SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','d3100000-0000-4000-8000-000000000002',true);
SELECT throws_ok($q$INSERT INTO public.romax_opportunities(organization_id,source_system,source_thread_id,source_message_id) VALUES ('d3100000-0000-4000-8000-000000000001','gmail','forged','forged')$q$,'42501',NULL,'owner cannot forge Gmail opportunity');
SELECT lives_ok($q$INSERT INTO public.romax_opportunities(organization_id,source_system,subject) VALUES ('d3100000-0000-4000-8000-000000000001','manual','Manual QA')$q$,'manual workflow remains available');
SELECT throws_ok($q$UPDATE public.romax_opportunities SET source_system='gmail',source_thread_id='forged',source_message_id='forged' WHERE organization_id='d3100000-0000-4000-8000-000000000001' AND source_system='manual'$q$,'42501',NULL,'manual provenance cannot become Gmail');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($q$SELECT public.romax_confirm_gmail_import('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000003','2026-01-01T00:00:00Z',repeat('c',64),repeat('b',64),clock_timestamp()+interval '4 minutes','manager-thread','manager-msg','Synthetic request','sender@example.test',clock_timestamp()-interval '1 minute','Synthetic excerpt','Synthetic classification')$q$,'42501',NULL,'non-owner cannot import');
SELECT throws_ok($q$SELECT public.romax_confirm_gmail_import('d3100000-0000-4000-8000-000000000004','d3100000-0000-4000-8000-000000000002','2026-01-01T00:00:00Z',repeat('c',64),repeat('b',64),clock_timestamp()+interval '4 minutes','wrong-tenant','wrong-msg','Synthetic request','sender@example.test',clock_timestamp()-interval '1 minute','Synthetic excerpt','Synthetic classification')$q$,'42501',NULL,'wrong tenant rejected');
SELECT throws_ok($q$SELECT public.romax_confirm_gmail_import('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000002','2026-01-01T00:00:00Z',repeat('c',64),repeat('b',64),clock_timestamp()-interval '1 minute','expired','expired-msg','Synthetic request','sender@example.test',clock_timestamp()-interval '1 minute','Synthetic excerpt','Synthetic classification')$q$,'22023',NULL,'expired confirmation rejected');
SELECT is((public.romax_confirm_gmail_import('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000002','2026-01-01T00:00:00Z',repeat('a',64),repeat('b',64),clock_timestamp()+interval '4 minutes','synthetic-thread','synthetic-msg','Synthetic request','sender@example.test',clock_timestamp()-interval '1 minute','Synthetic excerpt','Synthetic classification'))->>'outcome','imported','owner confirmation imports');
SELECT is((public.romax_confirm_gmail_import('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000002','2026-01-01T00:00:00Z',repeat('a',64),repeat('b',64),clock_timestamp()+interval '4 minutes','synthetic-thread','synthetic-msg','Synthetic request','sender@example.test',clock_timestamp()-interval '1 minute','Synthetic excerpt','Synthetic classification'))->>'outcome','already_exists','same confirmation is idempotent');
SELECT is((public.romax_confirm_gmail_import('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000002','2026-01-01T00:00:00Z',repeat('d',64),repeat('b',64),clock_timestamp()+interval '4 minutes','synthetic-thread','another-msg','Synthetic request','sender@example.test',clock_timestamp()-interval '1 minute','Synthetic excerpt','Synthetic classification'))->>'outcome','already_exists','same thread does not duplicate');
SELECT throws_ok($q$SELECT public.romax_confirm_gmail_import('d3100000-0000-4000-8000-000000000001','d3100000-0000-4000-8000-000000000002','2026-01-01T00:00:00Z',repeat('e',64),repeat('b',64),clock_timestamp()+interval '4 minutes','another-thread','synthetic-msg','Synthetic request','sender@example.test',clock_timestamp()-interval '1 minute','Synthetic excerpt','Synthetic classification')$q$,'23505',NULL,'same message cannot create another thread');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.romax_opportunities WHERE organization_id='d3100000-0000-4000-8000-000000000001' AND source_system='gmail'),1::bigint,'exactly one Gmail row');
SELECT is((SELECT count(*) FROM public.romax_gmail_import_audit WHERE organization_id='d3100000-0000-4000-8000-000000000001'),1::bigint,'exactly one audit row');
SELECT throws_ok($q$DELETE FROM public.romax_opportunities WHERE organization_id='d3100000-0000-4000-8000-000000000001' AND source_system='gmail'$q$,'42501',NULL,'Gmail history cannot be deleted');
SELECT * FROM finish();
ROLLBACK;
